CREATE TABLE IF NOT EXISTS "sections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent section. Null for a masthead-level section such as World or Business.
	"parent_id" BIGINT,
	-- Display name as printed in the navigation.
	"name" VARCHAR(80) NOT NULL,
	-- URL segment. Unique across the whole tree so a section can be moved without breaking its permalink.
	"slug" VARCHAR(90) NOT NULL UNIQUE,
	-- free | metered | subscriber. Inherited by new articles so a whole desk can be opened or closed at once.
	"default_access" VARCHAR(16) NOT NULL DEFAULT 'metered',
	-- Manual sort order among siblings on the front page.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sections" IS 'The masthead tree (adjacency list). It carries a default access level because paywall policy is usually set per desk, not per story.';
COMMENT ON COLUMN "sections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sections"."parent_id" IS 'Parent section. Null for a masthead-level section such as World or Business.';
COMMENT ON COLUMN "sections"."name" IS 'Display name as printed in the navigation.';
COMMENT ON COLUMN "sections"."slug" IS 'URL segment. Unique across the whole tree so a section can be moved without breaking its permalink.';
COMMENT ON COLUMN "sections"."default_access" IS 'free | metered | subscriber. Inherited by new articles so a whole desk can be opened or closed at once.';
COMMENT ON COLUMN "sections"."position" IS 'Manual sort order among siblings on the front page.';

CREATE TABLE IF NOT EXISTS "authors" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL segment for the author page.
	"slug" VARCHAR(90) NOT NULL UNIQUE,
	-- Byline exactly as it should be printed, including middle initials.
	"display_name" VARCHAR(120) NOT NULL,
	-- staff | contributor | wire | editor. Wire authors exist so syndicated copy still gets a byline row.
	"role" VARCHAR(24) NOT NULL DEFAULT 'staff',
	-- Short biography shown under the byline.
	"bio" TEXT,
	-- Contact address. Null for wire bylines that have no person behind them.
	"email" VARCHAR(320),
	-- Cleared when a journalist leaves; the byline stays on published work.
	"active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "authors" IS 'A byline. Deliberately separate from readers: a journalist who also subscribes is two rows, because the lifecycles and the deletion rules have nothing in common.';
COMMENT ON COLUMN "authors"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "authors"."slug" IS 'URL segment for the author page.';
COMMENT ON COLUMN "authors"."display_name" IS 'Byline exactly as it should be printed, including middle initials.';
COMMENT ON COLUMN "authors"."role" IS 'staff | contributor | wire | editor. Wire authors exist so syndicated copy still gets a byline row.';
COMMENT ON COLUMN "authors"."bio" IS 'Short biography shown under the byline.';
COMMENT ON COLUMN "authors"."email" IS 'Contact address. Null for wire bylines that have no person behind them.';
COMMENT ON COLUMN "authors"."active" IS 'Cleared when a journalist leaves; the byline stays on published work.';

CREATE TABLE IF NOT EXISTS "articles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Desk the story sits under. Null while a story is still in the drafts pile.
	"section_id" BIGINT,
	-- Revision currently served to readers. Null until first publish, which is what makes publish an atomic pointer swap.
	"live_revision_id" BIGINT,
	-- URL segment. Never changed after publish; a corrected headline does not move the story.
	"slug" VARCHAR(200) NOT NULL UNIQUE,
	-- Short label above the headline, e.g. Analysis or Live.
	"kicker" VARCHAR(120),
	-- free | metered | subscriber. Copied from the section at creation, then editable per story.
	"access_level" VARCHAR(16) NOT NULL DEFAULT 'metered',
	-- draft | scheduled | published | unpublished.
	"status" VARCHAR(16) NOT NULL DEFAULT 'draft',
	-- First publication instant. Null for drafts; the sort key for every feed.
	"published_at" TIMESTAMPTZ,
	-- Last edit to any part of the record.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Denormalised from the live revision so list pages can show read time without loading bodies.
	"word_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "articles" IS 'The stable identity of a story. It holds no body text at all - only the pointer to the revision that is live, so publishing and rolling back are one UPDATE.';
COMMENT ON COLUMN "articles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "articles"."section_id" IS 'Desk the story sits under. Null while a story is still in the drafts pile.';
COMMENT ON COLUMN "articles"."live_revision_id" IS 'Revision currently served to readers. Null until first publish, which is what makes publish an atomic pointer swap.';
COMMENT ON COLUMN "articles"."slug" IS 'URL segment. Never changed after publish; a corrected headline does not move the story.';
COMMENT ON COLUMN "articles"."kicker" IS 'Short label above the headline, e.g. Analysis or Live.';
COMMENT ON COLUMN "articles"."access_level" IS 'free | metered | subscriber. Copied from the section at creation, then editable per story.';
COMMENT ON COLUMN "articles"."status" IS 'draft | scheduled | published | unpublished.';
COMMENT ON COLUMN "articles"."published_at" IS 'First publication instant. Null for drafts; the sort key for every feed.';
COMMENT ON COLUMN "articles"."updated_at" IS 'Last edit to any part of the record.';
COMMENT ON COLUMN "articles"."word_count" IS 'Denormalised from the live revision so list pages can show read time without loading bodies.';

CREATE INDEX "idx_articles_status_published"
ON "articles" ("status", "published_at");
CREATE INDEX "idx_articles_section_published"
ON "articles" ("section_id", "published_at");

CREATE TABLE IF NOT EXISTS "article_revisions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Story this revision belongs to.
	"article_id" BIGINT NOT NULL,
	-- Monotonic per article, starting at 1. What editors cite in a correction notice.
	"revision_number" INTEGER NOT NULL,
	-- Headline for this revision. Headlines are A/B tested and rewritten, so they version with the body.
	"headline" VARCHAR(300) NOT NULL,
	-- Deck or summary paragraph under the headline.
	"standfirst" VARCHAR(600),
	-- Full article body, stored as structured Markdown.
	"body" TEXT NOT NULL,
	-- How much of body the paywall renders to a blocked reader. Per revision because a rewrite changes where the natural cut is.
	"free_excerpt_chars" INTEGER NOT NULL DEFAULT 600,
	-- Why this revision exists. Populated for corrections, which must be disclosed.
	"change_note" VARCHAR(400),
	-- Author who saved the revision. Null when an automated import wrote it.
	"created_by" BIGINT,
	-- When the revision was saved.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "article_revisions" IS 'Append-only history of a story. Nothing here is ever updated, which is what lets a newsroom prove what was printed at a given minute during a dispute.';
COMMENT ON COLUMN "article_revisions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "article_revisions"."article_id" IS 'Story this revision belongs to.';
COMMENT ON COLUMN "article_revisions"."revision_number" IS 'Monotonic per article, starting at 1. What editors cite in a correction notice.';
COMMENT ON COLUMN "article_revisions"."headline" IS 'Headline for this revision. Headlines are A/B tested and rewritten, so they version with the body.';
COMMENT ON COLUMN "article_revisions"."standfirst" IS 'Deck or summary paragraph under the headline.';
COMMENT ON COLUMN "article_revisions"."body" IS 'Full article body, stored as structured Markdown.';
COMMENT ON COLUMN "article_revisions"."free_excerpt_chars" IS 'How much of body the paywall renders to a blocked reader. Per revision because a rewrite changes where the natural cut is.';
COMMENT ON COLUMN "article_revisions"."change_note" IS 'Why this revision exists. Populated for corrections, which must be disclosed.';
COMMENT ON COLUMN "article_revisions"."created_by" IS 'Author who saved the revision. Null when an automated import wrote it.';
COMMENT ON COLUMN "article_revisions"."created_at" IS 'When the revision was saved.';

CREATE UNIQUE INDEX "uq_revisions_article_number"
ON "article_revisions" ("article_id", "revision_number");

CREATE TABLE IF NOT EXISTS "article_authors" (
	-- Story being credited.
	"article_id" BIGINT,
	-- Byline being credited.
	"author_id" BIGINT,
	-- Order the bylines are printed in. Lead writer is 0.
	"position" INTEGER NOT NULL DEFAULT 0,
	-- Secondary credit such as reporting, photography or additional reporting.
	"contribution" VARCHAR(40),
	PRIMARY KEY("article_id", "author_id")
);

COMMENT ON TABLE "article_authors" IS 'Co-bylines as a join table. A single author_id column on articles cannot express reporting credits, which appear on a large share of investigative work.';
COMMENT ON COLUMN "article_authors"."article_id" IS 'Story being credited.';
COMMENT ON COLUMN "article_authors"."author_id" IS 'Byline being credited.';
COMMENT ON COLUMN "article_authors"."position" IS 'Order the bylines are printed in. Lead writer is 0.';
COMMENT ON COLUMN "article_authors"."contribution" IS 'Secondary credit such as reporting, photography or additional reporting.';

CREATE TABLE IF NOT EXISTS "readers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. Null for an anonymous reader who is only being metered by cookie.
	"email" VARCHAR(320) UNIQUE,
	-- Long-lived first-party cookie value. Present for everyone, which is what lets the meter start counting before signup.
	"anonymous_key" VARCHAR(64) NOT NULL UNIQUE,
	-- Name shown on comments. Null until the reader chooses one.
	"display_name" VARCHAR(120),
	-- When an email was attached. Null means this row is still a pure anonymous device.
	"registered_at" TIMESTAMPTZ,
	-- ok | limited | banned. Enforced before a comment row is even created.
	"comment_status" VARCHAR(16) NOT NULL DEFAULT 'ok',
	-- First time this reader was seen.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "readers" IS 'One row per reader, anonymous or registered. Registration attaches an email to an existing row rather than creating a new one, so the meter count survives signup.';
COMMENT ON COLUMN "readers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "readers"."email" IS 'Login identity. Null for an anonymous reader who is only being metered by cookie.';
COMMENT ON COLUMN "readers"."anonymous_key" IS 'Long-lived first-party cookie value. Present for everyone, which is what lets the meter start counting before signup.';
COMMENT ON COLUMN "readers"."display_name" IS 'Name shown on comments. Null until the reader chooses one.';
COMMENT ON COLUMN "readers"."registered_at" IS 'When an email was attached. Null means this row is still a pure anonymous device.';
COMMENT ON COLUMN "readers"."comment_status" IS 'ok | limited | banned. Enforced before a comment row is even created.';
COMMENT ON COLUMN "readers"."created_at" IS 'First time this reader was seen.';

CREATE TABLE IF NOT EXISTS "plans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine name such as digital_basic. Used in entitlement checks so renaming the marketing label is safe.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Customer-facing plan name.
	"name" VARCHAR(120) NOT NULL,
	-- Recurring price in minor units. Integers only - never float money.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency for price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- month | year. Drives renewal date arithmetic.
	"interval" VARCHAR(12) NOT NULL DEFAULT 'month',
	-- Free articles per period for readers on this plan. Zero means a hard wall.
	"meter_limit" INTEGER NOT NULL DEFAULT 5,
	-- Gift links mintable per period. Zero for entry plans, which is the whole lever behind gifting as a growth channel.
	"gift_allowance" INTEGER NOT NULL DEFAULT 0,
	-- Whether pre-digital archive articles are unlocked.
	"includes_archive" BOOLEAN NOT NULL DEFAULT false,
	-- Retired plans stay for existing subscribers but leave the pricing page.
	"active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "plans" IS 'The commercial catalogue, including the anonymous default. Meter and gift limits live here rather than in application config so a price experiment is a data change.';
COMMENT ON COLUMN "plans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "plans"."code" IS 'Stable machine name such as digital_basic. Used in entitlement checks so renaming the marketing label is safe.';
COMMENT ON COLUMN "plans"."name" IS 'Customer-facing plan name.';
COMMENT ON COLUMN "plans"."price_cents" IS 'Recurring price in minor units. Integers only - never float money.';
COMMENT ON COLUMN "plans"."currency_code" IS 'ISO 4217 currency for price_cents.';
COMMENT ON COLUMN "plans"."interval" IS 'month | year. Drives renewal date arithmetic.';
COMMENT ON COLUMN "plans"."meter_limit" IS 'Free articles per period for readers on this plan. Zero means a hard wall.';
COMMENT ON COLUMN "plans"."gift_allowance" IS 'Gift links mintable per period. Zero for entry plans, which is the whole lever behind gifting as a growth channel.';
COMMENT ON COLUMN "plans"."includes_archive" IS 'Whether pre-digital archive articles are unlocked.';
COMMENT ON COLUMN "plans"."active" IS 'Retired plans stay for existing subscribers but leave the pricing page.';

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscriber.
	"reader_id" BIGINT NOT NULL,
	-- Plan being paid for.
	"plan_id" BIGINT NOT NULL,
	-- trialing | active | past_due | cancelled | expired.
	"status" VARCHAR(20) NOT NULL DEFAULT 'trialing',
	-- Billing provider subscription id. Unique so a replayed webhook cannot create a second entitlement.
	"provider_reference" VARCHAR(120) UNIQUE,
	-- Start of the paid period currently entitling the reader.
	"current_period_start" TIMESTAMPTZ NOT NULL,
	-- When access lapses unless renewal succeeds. The single column every entitlement check reads.
	"current_period_end" TIMESTAMPTZ NOT NULL,
	-- Set when a reader cancels but has already paid through the period.
	"cancel_at_period_end" BOOLEAN NOT NULL DEFAULT false,
	-- First subscription start, kept across plan changes for tenure reporting.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'Paid access. A reader can have several rows over time but at most one non-terminal row, which is how a lapsed-then-resubscribed reader keeps their history.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."reader_id" IS 'Subscriber.';
COMMENT ON COLUMN "subscriptions"."plan_id" IS 'Plan being paid for.';
COMMENT ON COLUMN "subscriptions"."status" IS 'trialing | active | past_due | cancelled | expired.';
COMMENT ON COLUMN "subscriptions"."provider_reference" IS 'Billing provider subscription id. Unique so a replayed webhook cannot create a second entitlement.';
COMMENT ON COLUMN "subscriptions"."current_period_start" IS 'Start of the paid period currently entitling the reader.';
COMMENT ON COLUMN "subscriptions"."current_period_end" IS 'When access lapses unless renewal succeeds. The single column every entitlement check reads.';
COMMENT ON COLUMN "subscriptions"."cancel_at_period_end" IS 'Set when a reader cancels but has already paid through the period.';
COMMENT ON COLUMN "subscriptions"."started_at" IS 'First subscription start, kept across plan changes for tenure reporting.';

CREATE INDEX "idx_subscriptions_reader_status"
ON "subscriptions" ("reader_id", "status");
CREATE INDEX "idx_subscriptions_period_end"
ON "subscriptions" ("current_period_end");

CREATE TABLE IF NOT EXISTS "meter_periods" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Reader being metered.
	"reader_id" BIGINT NOT NULL,
	-- First local date of the meter window, normally the first of the calendar month.
	"period_start" DATE NOT NULL,
	-- Last local date of the window, inclusive.
	"period_end" DATE NOT NULL,
	-- Running count of distinct metered articles. Incremented only when a meter_views insert actually created a row.
	"articles_viewed" INTEGER NOT NULL DEFAULT 0,
	-- Free articles granted for this window, snapshotted from the plan so a mid-period price change cannot retroactively wall a reader.
	"allowance" INTEGER NOT NULL,
	-- Most recent metered read. Drives the nudge that appears at one article remaining.
	"last_viewed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "meter_periods" IS 'One row per reader per meter window, holding the counter itself. Every paywall decision is this single indexed row read - no aggregation over the view log at request time.';
COMMENT ON COLUMN "meter_periods"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "meter_periods"."reader_id" IS 'Reader being metered.';
COMMENT ON COLUMN "meter_periods"."period_start" IS 'First local date of the meter window, normally the first of the calendar month.';
COMMENT ON COLUMN "meter_periods"."period_end" IS 'Last local date of the window, inclusive.';
COMMENT ON COLUMN "meter_periods"."articles_viewed" IS 'Running count of distinct metered articles. Incremented only when a meter_views insert actually created a row.';
COMMENT ON COLUMN "meter_periods"."allowance" IS 'Free articles granted for this window, snapshotted from the plan so a mid-period price change cannot retroactively wall a reader.';
COMMENT ON COLUMN "meter_periods"."last_viewed_at" IS 'Most recent metered read. Drives the nudge that appears at one article remaining.';

CREATE UNIQUE INDEX "uq_meter_periods_reader_start"
ON "meter_periods" ("reader_id", "period_start");

CREATE TABLE IF NOT EXISTS "meter_views" (
	-- Window the read is charged to.
	"meter_period_id" BIGINT,
	-- Article read. Part of the primary key, which is the whole dedupe mechanism.
	"article_id" BIGINT,
	-- When the article first consumed a credit in this window.
	"first_viewed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- meter | gift | search | newsletter. Records why the read was allowed, which is what makes referrer exemptions auditable.
	"unlocked_by" VARCHAR(16) NOT NULL DEFAULT 'meter',
	PRIMARY KEY("meter_period_id", "article_id")
);

COMMENT ON TABLE "meter_views" IS 'The ledger behind the counter. Reads are recorded with INSERT ON CONFLICT DO NOTHING, so re-opening the same story is free and the counter only moves when a row is genuinely new.';
COMMENT ON COLUMN "meter_views"."meter_period_id" IS 'Window the read is charged to.';
COMMENT ON COLUMN "meter_views"."article_id" IS 'Article read. Part of the primary key, which is the whole dedupe mechanism.';
COMMENT ON COLUMN "meter_views"."first_viewed_at" IS 'When the article first consumed a credit in this window.';
COMMENT ON COLUMN "meter_views"."unlocked_by" IS 'meter | gift | search | newsletter. Records why the read was allowed, which is what makes referrer exemptions auditable.';

CREATE TABLE IF NOT EXISTS "gift_links" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Story being unlocked.
	"article_id" BIGINT NOT NULL,
	-- Subscriber who created the link, so an abused allowance can be traced to an account.
	"minted_by" BIGINT NOT NULL,
	-- Opaque URL token. Long and random because possession of it is the entire authorisation.
	"token" VARCHAR(64) NOT NULL UNIQUE,
	-- Redemption cap. What stops one gift link becoming a public bypass on social media.
	"max_redemptions" INTEGER NOT NULL DEFAULT 10,
	-- Redemptions consumed so far, incremented under the same transaction that grants access.
	"redemptions_used" INTEGER NOT NULL DEFAULT 0,
	-- Hard expiry, typically 14 days. A gift is a loan of access, not a permanent hole in the wall.
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- Set when abuse is detected. Kept rather than deleted so the link resolves to a clear message.
	"revoked_at" TIMESTAMPTZ,
	-- Mint time, also used to charge the allowance to the right period.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "gift_links" IS 'A capability token with its own lifetime, cap and owner. None of that fits on articles or on the meter, and unlike an entitlement it must work for a reader with no account at all.';
COMMENT ON COLUMN "gift_links"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "gift_links"."article_id" IS 'Story being unlocked.';
COMMENT ON COLUMN "gift_links"."minted_by" IS 'Subscriber who created the link, so an abused allowance can be traced to an account.';
COMMENT ON COLUMN "gift_links"."token" IS 'Opaque URL token. Long and random because possession of it is the entire authorisation.';
COMMENT ON COLUMN "gift_links"."max_redemptions" IS 'Redemption cap. What stops one gift link becoming a public bypass on social media.';
COMMENT ON COLUMN "gift_links"."redemptions_used" IS 'Redemptions consumed so far, incremented under the same transaction that grants access.';
COMMENT ON COLUMN "gift_links"."expires_at" IS 'Hard expiry, typically 14 days. A gift is a loan of access, not a permanent hole in the wall.';
COMMENT ON COLUMN "gift_links"."revoked_at" IS 'Set when abuse is detected. Kept rather than deleted so the link resolves to a clear message.';
COMMENT ON COLUMN "gift_links"."created_at" IS 'Mint time, also used to charge the allowance to the right period.';

CREATE INDEX "idx_gift_links_minter_created"
ON "gift_links" ("minted_by", "created_at");
CREATE INDEX "idx_gift_links_article"
ON "gift_links" ("article_id");

CREATE TABLE IF NOT EXISTS "newsletters" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine name such as morning_briefing.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Customer-facing newsletter title.
	"name" VARCHAR(120) NOT NULL,
	-- One-line pitch shown on the signup page.
	"description" VARCHAR(400),
	-- daily | weekdays | weekly | occasional.
	"cadence" VARCHAR(20) NOT NULL DEFAULT 'daily',
	-- Restricts signup to paying readers; some newsletters are a retention perk.
	"subscriber_only" BOOLEAN NOT NULL DEFAULT false,
	-- Cleared when a newsletter is retired; signups are kept for the archive.
	"active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "newsletters" IS 'A newsletter product. Separate from sends because a reader signs up to the product, not to an edition.';
COMMENT ON COLUMN "newsletters"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "newsletters"."code" IS 'Stable machine name such as morning_briefing.';
COMMENT ON COLUMN "newsletters"."name" IS 'Customer-facing newsletter title.';
COMMENT ON COLUMN "newsletters"."description" IS 'One-line pitch shown on the signup page.';
COMMENT ON COLUMN "newsletters"."cadence" IS 'daily | weekdays | weekly | occasional.';
COMMENT ON COLUMN "newsletters"."subscriber_only" IS 'Restricts signup to paying readers; some newsletters are a retention perk.';
COMMENT ON COLUMN "newsletters"."active" IS 'Cleared when a newsletter is retired; signups are kept for the archive.';

CREATE TABLE IF NOT EXISTS "newsletter_signups" (
	-- Newsletter subscribed to.
	"newsletter_id" BIGINT,
	-- Reader subscribed.
	"reader_id" BIGINT,
	-- active | unsubscribed | bounced. Bounced is distinct because it is not a reader decision and can be repaired.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Where the signup came from, e.g. article_inline or onboarding. The only honest way to compare acquisition surfaces.
	"source" VARCHAR(40),
	-- Signup time.
	"subscribed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Set on opt-out. The row is kept so a resubscribe does not look like a new reader.
	"unsubscribed_at" TIMESTAMPTZ,
	PRIMARY KEY("newsletter_id", "reader_id")
);

COMMENT ON TABLE "newsletter_signups" IS 'Signups as a join table with state. Rows are never deleted on unsubscribe, because suppression lists have to outlive the relationship they suppress.';
COMMENT ON COLUMN "newsletter_signups"."newsletter_id" IS 'Newsletter subscribed to.';
COMMENT ON COLUMN "newsletter_signups"."reader_id" IS 'Reader subscribed.';
COMMENT ON COLUMN "newsletter_signups"."status" IS 'active | unsubscribed | bounced. Bounced is distinct because it is not a reader decision and can be repaired.';
COMMENT ON COLUMN "newsletter_signups"."source" IS 'Where the signup came from, e.g. article_inline or onboarding. The only honest way to compare acquisition surfaces.';
COMMENT ON COLUMN "newsletter_signups"."subscribed_at" IS 'Signup time.';
COMMENT ON COLUMN "newsletter_signups"."unsubscribed_at" IS 'Set on opt-out. The row is kept so a resubscribe does not look like a new reader.';

CREATE TABLE IF NOT EXISTS "newsletter_sends" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Newsletter this edition belongs to.
	"newsletter_id" BIGINT NOT NULL,
	-- Subject line as sent. Snapshotted because subject tests are the main lever on open rate.
	"subject" VARCHAR(300) NOT NULL,
	-- Story at the top of the edition. Null for a digest with no single lead.
	"lead_article_id" BIGINT,
	-- Intended send instant.
	"scheduled_for" TIMESTAMPTZ NOT NULL,
	-- Actual send instant. Null while queued, which is also how a stuck send is found.
	"sent_at" TIMESTAMPTZ,
	-- Recipients at send time. Frozen, because the signup list keeps moving afterwards.
	"recipient_count" INTEGER NOT NULL DEFAULT 0,
	-- Unique opens, updated from provider events.
	"open_count" INTEGER NOT NULL DEFAULT 0,
	-- Unique clicks, updated from provider events.
	"click_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "newsletter_sends" IS 'One row per edition. Counts are denormalised here rather than derived from an event log, because editors need them on the dashboard the minute a send finishes.';
COMMENT ON COLUMN "newsletter_sends"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "newsletter_sends"."newsletter_id" IS 'Newsletter this edition belongs to.';
COMMENT ON COLUMN "newsletter_sends"."subject" IS 'Subject line as sent. Snapshotted because subject tests are the main lever on open rate.';
COMMENT ON COLUMN "newsletter_sends"."lead_article_id" IS 'Story at the top of the edition. Null for a digest with no single lead.';
COMMENT ON COLUMN "newsletter_sends"."scheduled_for" IS 'Intended send instant.';
COMMENT ON COLUMN "newsletter_sends"."sent_at" IS 'Actual send instant. Null while queued, which is also how a stuck send is found.';
COMMENT ON COLUMN "newsletter_sends"."recipient_count" IS 'Recipients at send time. Frozen, because the signup list keeps moving afterwards.';
COMMENT ON COLUMN "newsletter_sends"."open_count" IS 'Unique opens, updated from provider events.';
COMMENT ON COLUMN "newsletter_sends"."click_count" IS 'Unique clicks, updated from provider events.';

CREATE INDEX "idx_sends_newsletter_scheduled"
ON "newsletter_sends" ("newsletter_id", "scheduled_for");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Story being discussed.
	"article_id" BIGINT NOT NULL,
	-- Author of the comment.
	"reader_id" BIGINT NOT NULL,
	-- Comment being replied to. Null for a top-level comment.
	"parent_id" BIGINT,
	-- Comment text as submitted. Never edited in place; a change writes a new row and hides this one.
	"body" TEXT NOT NULL,
	-- pending | approved | rejected | auto_held. auto_held is a classifier decision awaiting a human.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Editor who decided. Null while pending or when a classifier auto-approved.
	"moderated_by" BIGINT,
	-- Why it was rejected. Shown to the commenter, so vague reasons cost support time.
	"moderation_reason" VARCHAR(200),
	-- Reader reports. Crossing a threshold flips status back to pending.
	"flag_count" INTEGER NOT NULL DEFAULT 0,
	-- Submission time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Threaded comments with an explicit moderation state. Default pending rather than approved means a queue backlog degrades into silence, not into abuse on the page.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."article_id" IS 'Story being discussed.';
COMMENT ON COLUMN "comments"."reader_id" IS 'Author of the comment.';
COMMENT ON COLUMN "comments"."parent_id" IS 'Comment being replied to. Null for a top-level comment.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text as submitted. Never edited in place; a change writes a new row and hides this one.';
COMMENT ON COLUMN "comments"."status" IS 'pending | approved | rejected | auto_held. auto_held is a classifier decision awaiting a human.';
COMMENT ON COLUMN "comments"."moderated_by" IS 'Editor who decided. Null while pending or when a classifier auto-approved.';
COMMENT ON COLUMN "comments"."moderation_reason" IS 'Why it was rejected. Shown to the commenter, so vague reasons cost support time.';
COMMENT ON COLUMN "comments"."flag_count" IS 'Reader reports. Crossing a threshold flips status back to pending.';
COMMENT ON COLUMN "comments"."created_at" IS 'Submission time.';

CREATE INDEX "idx_comments_article_status_created"
ON "comments" ("article_id", "status", "created_at");
CREATE INDEX "idx_comments_moderation_queue"
ON "comments" ("status", "created_at");

